#include "codane/graph.hpp"
#include "codane/codex_provider.hpp"
#include <future>
#include <fstream>
#include <iostream>
#include <thread>
#include <unistd.h>
using namespace codane;static bool json_mode=false;
static void help(){std::ostream&o=json_mode?std::cerr:std::cout;o<<"codane 0.1.0\nUsage: codane [--events-json] <run|resume|status|inspect|cancel|validate|version> [arg] [--provider fake|codex]\n";}
static std::filesystem::path runroot(const std::string&id){return std::filesystem::path(".codane")/"runs"/id;}static std::string rid(){return std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());}static void emit(const Event&e){if(json_mode)std::cout<<e.json().dump()<<'\n';}
static void save(const std::filesystem::path&root,const std::string&id,const Graph&g,const Journal&j){atomic_write(root/"snapshot.json",Json(Json::object{{"run_id",id},{"graph",graph_json(g)},{"event_sequence",(double)j.last_sequence()},{"loop_iterations",0}}).dump());}
static std::unique_ptr<Verifier> verifier_from(const Json&j,const std::filesystem::path&dir,const std::stop_token&st){auto type=j.at("type").str();if(type=="command"){ProcessSpec p;p.argv.clear();for(auto const&x:j.at("command").arr())p.argv.push_back(x.str());p.cwd=dir.string();p.stop=st;return std::make_unique<CommandVerifier>(p);}if(type=="file_exists"){auto path=j.at("path").str();return std::make_unique<FileExistsVerifier>(std::filesystem::path(path).is_absolute()?std::filesystem::path(path):dir/path);}if(type=="file_content"){auto path=j.at("path").str();return std::make_unique<FileContentVerifier>(std::filesystem::path(path).is_absolute()?std::filesystem::path(path):dir/path,(j.has("content")?j.at("content"):j.at("expected")).str());}if(type=="all_of"){std::vector<std::unique_ptr<Verifier>>vs;for(auto const&x:(j.has("verifiers")?j.at("verifiers"):j.at("members")).arr())vs.push_back(verifier_from(x,dir,st));return std::make_unique<AllOfVerifier>(std::move(vs));}throw std::runtime_error("unknown verifier type: "+type);}
static AgentResult one(AgentProvider&provider,const Node&n,const Graph&g,const std::filesystem::path&root,const std::filesystem::path&project_workspace,Cancellation&c){auto dir=root/"artifacts"/n.id;if(n.type=="command"){ProcessSpec p;p.argv=n.command;p.cwd=dir.string();p.timeout=g.limits.process_timeout;p.max_stdout=g.limits.max_stdout;p.max_stderr=g.limits.max_stderr;p.stop=c.source.get_token();p.cancel_file=root/"cancelled";auto r=run_process(p);AgentResult a;a.exit_code=r.exit_code;a.signal=r.signal;a.stdout_text=r.stdout_text;a.stderr_text=r.stderr_text;a.stdout_truncated=r.stdout_truncated;a.stderr_truncated=r.stderr_truncated;a.status=(r.exit_code==0&&r.signal==0)?NodeState::Succeeded:((c.cancelled()||r.cancelled)?NodeState::Cancelled:NodeState::Failed);if(a.status==NodeState::Succeeded&&n.verifier){std::string error;auto v=verifier_from(*n.verifier,dir,c.source.get_token());a.verifier_ran=true;a.verifier_error=error;if(!v->verify(&error)){a.status=NodeState::Failed;a.stderr_text=error;a.verifier_error=error;}}return a;}AgentRequest q;q.id=n.id;q.name=n.id;q.prompt=n.prompt;q.attempt=n.attempts+1;q.timeout=g.limits.process_timeout;q.workspace=project_workspace.string();try{populate_artifacts(q,n,root);}catch(const std::exception&e){AgentResult a;a.status=NodeState::Failed;a.stderr_text=e.what();return a;}if(!n.verifier)return provider.run(q,c.source.get_token());return run_verified(provider,q,g.retry,c,[&]{return verifier_from(*n.verifier,dir,c.source.get_token());});}
static int execute(Graph&g,const std::string&id,AgentProvider&provider,bool resume=false){auto root=runroot(id);auto project_workspace=std::filesystem::current_path();std::filesystem::create_directories(root/"artifacts");Journal j(root/"events.jsonl");Cancellation cancel;atomic_write(root/"runner.json",Json(Json::object{{"pid",(double)getpid()},{"run_id",id},{"owner",std::string("codane")}}).dump());std::jthread watcher([&](std::stop_token st){while(!st.stop_requested()&&!cancel.cancelled()){if(std::filesystem::exists(root/"cancelled"))cancel.cancel();std::this_thread::sleep_for(std::chrono::milliseconds(10));}});if(!resume)j.append("run_started",id,"",Json::object{{"name",g.name}});for(auto&[nid,n]:g.nodes){n.artifact_dir=(root/"artifacts"/nid).string();std::filesystem::create_directories(n.artifact_dir);}
 size_t done=0;for(auto&[_,n]:g.nodes)if(n.state==NodeState::Succeeded&&n.verified)++done;while(done<g.nodes.size()&&!cancel.cancelled()){auto ready=g.ready();if(ready.empty()){bool pending=false;for(auto&[_,n]:g.nodes)if(n.state==NodeState::Pending){pending=true;n.state=NodeState::Blocked;}if(pending)break;}
  std::vector<std::future<std::pair<NodeId,AgentResult>>>jobs;for(auto const&nid:ready){if(jobs.size()>=g.limits.max_parallel)break;auto&n=g.nodes[nid];n.state=NodeState::Running;j.append("node_started",id,nid,Json::object{{"attempt",n.attempts+1}});emit(j.replay().back());save(root,id,g,j);jobs.push_back(std::async(std::launch::async,[&,nid]{return std::make_pair(nid,one(provider,g.nodes.at(nid),g,root,project_workspace,cancel));}));}
  for(auto&f:jobs){auto[nid,a]=f.get();auto&n=g.nodes[nid];++n.attempts;if(a.status==NodeState::Succeeded){n.state=NodeState::Succeeded;n.verified=n.accepted=true;++done;}else if(a.status==NodeState::Cancelled)n.state=NodeState::Cancelled;else if(n.attempts<g.retry.max_attempts){n.state=NodeState::Pending;n.retry_pending=1;auto delay=g.retry.backoff;for(int k=1;k<n.attempts;k++)delay=std::chrono::milliseconds(std::min<int64_t>(delay.count()*g.retry.multiplier,60000));std::this_thread::sleep_for(std::min(delay,std::chrono::milliseconds(20)));n.retry_pending=0;}else n.state=NodeState::Failed;Json::object payload{{"attempt",n.attempts},{"verified",n.verified},{"verifier_ran",a.verifier_ran},{"verifier_error",a.verifier_error},{"stdout",a.stdout_text},{"stderr",a.stderr_text}};j.append(n.state==NodeState::Succeeded?"node_succeeded":n.state==NodeState::Cancelled?"node_cancelled":"node_failed",id,nid,payload);emit(j.replay().back());save(root,id,g,j);if(n.state==NodeState::Failed&&g.fail_fast){for(auto&[_,z]:g.nodes)if(z.state==NodeState::Pending)z.state=NodeState::Blocked;done=g.nodes.size();break;}}
 }if(cancel.cancelled())for(auto&[_,n]:g.nodes)if(n.state==NodeState::Running||n.state==NodeState::Pending)n.state=NodeState::Cancelled;j.append("run_finished",id,"",Json::object{{"completed",(double)done},{"cancelled",cancel.cancelled()}});emit(j.replay().back());save(root,id,g,j);watcher.request_stop();std::error_code ec;std::filesystem::remove(root/"runner.json",ec);bool success=!cancel.cancelled();for(auto const&[_,n]:g.nodes)if(n.state!=NodeState::Succeeded)success=false;return success?0:1;}
static Graph recover(const std::string&id){auto root=runroot(id);std::ifstream f(root/"snapshot.json");if(!f)throw std::runtime_error("missing snapshot for run: "+id);std::string s((std::istreambuf_iterator<char>(f)),{});Json j;try{j=Json::parse(s);}catch(...){throw std::runtime_error("malformed snapshot: "+(root/"snapshot.json").string());}if(!j.has("run_id")||j.at("run_id").str()!=id||!j.has("graph")||!j.has("event_sequence"))throw std::runtime_error("invalid snapshot");Graph g=graph_from_json(j.at("graph"));Journal journal(root/"events.jsonl");auto events=journal.replay();uint64_t checkpoint=(uint64_t)j.at("event_sequence").number();for(auto const&e:events)if(e.sequence>checkpoint&&e.node_id!=""&&g.nodes.count(e.node_id)){auto&n=g.nodes[e.node_id];if(e.event_type=="node_started")n.state=NodeState::Running;else if(e.event_type=="node_succeeded"){n.state=NodeState::Succeeded;n.verified=n.accepted=true;n.attempts=(int)e.payload.at("attempt").number();}else if(e.event_type=="node_failed"){n.state=NodeState::Failed;n.attempts=(int)e.payload.at("attempt").number();}else if(e.event_type=="node_cancelled")n.state=NodeState::Cancelled;}for(auto&[_,n]:g.nodes)if(n.state==NodeState::Running)n.state=NodeState::Pending;g.validate();return g;}
int main(int argc,char**argv){try{int i=1;for(;i<argc;i++)if(std::string(argv[i])=="--events-json")json_mode=true;if(argc<2){help();return 0;}std::string cmd;for(i=1;i<argc;i++)if(std::string(argv[i])!="--events-json"){cmd=argv[i];break;}if(cmd=="--help"){help();return 0;}if(cmd=="version"){if(json_mode)std::cout<<Json(Json::object{{"schema_version",1},{"sequence",1},{"timestamp",""},{"event_type","version"},{"version","0.1.0"}}).dump()<<"\n";else std::cout<<"0.1.0\n";return 0;}if(cmd=="validate"){if(i+1>=argc)throw std::runtime_error("validate requires graph");auto g=load_graph(argv[i+1]);if(json_mode)std::cout<<Json(Json::object{{"schema_version",1},{"sequence",1},{"timestamp",""},{"event_type","validated"},{"graph",g.name}}).dump()<<'\n';else std::cout<<"valid: "<<g.name<<" ("<<g.nodes.size()<<" nodes)\n";return 0;}if(cmd=="run"){if(i+1>=argc)throw std::runtime_error("run requires graph");auto g=load_graph(argv[i+1]);std::string provider="fake";for(int k=i+2;k<argc;k++)if(std::string(argv[k])=="--provider"&&k+1<argc)provider=argv[++k];std::string id=rid();if(provider=="codex"){CodexProvider p;int rc=execute(g,id,p);if(!json_mode)std::cout<<"run "<<id<<" "<<(rc?"failed":"succeeded")<<'\n';return rc;}if(provider!="fake")throw std::runtime_error("unknown provider: "+provider);FakeProvider p;int rc=execute(g,id,p);if(!json_mode)std::cout<<"run "<<id<<" "<<(rc?"failed":"succeeded")<<'\n';return rc;}if(cmd=="resume"){if(i+1>=argc)throw std::runtime_error("resume requires run id");auto g=recover(argv[i+1]);FakeProvider p;int rc=execute(g,argv[i+1],p,true);if(!json_mode)std::cout<<"resume "<<argv[i+1]<<" "<<(rc?"failed":"succeeded")<<'\n';return rc;}if(cmd=="status"||cmd=="inspect"){if(i+1>=argc)throw std::runtime_error("command requires run id");Journal j(runroot(argv[i+1])/"events.jsonl");auto e=j.replay();if(json_mode)for(auto&x:e)emit(x);else std::cout<<cmd<<": "<<argv[i+1]<<" events="<<e.size()<<'\n';return 0;}if(cmd=="cancel"){if(i+1>=argc)throw std::runtime_error("cancel requires run id");auto root=runroot(argv[i+1]);if(!std::filesystem::exists(root))throw std::runtime_error("unknown run: "+std::string(argv[i+1]));std::ofstream(root/"cancelled",std::ios::app)<<"cancel\n";if(json_mode)std::cout<<Json(Json::object{{"schema_version",1},{"sequence",1},{"timestamp",""},{"run_id",std::string(argv[i+1])},{"event_type","cancel_requested"}}).dump()<<'\n';else std::cout<<"cancel requested: "<<argv[i+1]<<'\n';return 0;}throw std::runtime_error("unknown command");}catch(std::exception&e){std::cerr<<"codane: "<<e.what()<<'\n';return 2;}}
